public final class MainActivity extends Activity {
 private WebView web; private Api api; private TextToSpeech tts;
 private final Handler main=new Handler(Looper.getMainLooper());
 private final ExecutorService worker=Executors.newSingleThreadExecutor();
 private String selected="admirito",target="oraculo",conversation="";
 private MediaRecorder recorder; private File commandFile;
 private volatile boolean foreground,busy,holding,recording,wake,awaitingWakeCommand;
 private SpeechRecognizer recognizer; private JSONObject challenge; private long pairUntil;
 private final Runnable refresh= new Runnable(){public void run(){if(foreground){if(!busy&&api!=null&&!api.account().isEmpty())history();main.postDelayed(this,15000);}}};
 @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setStatusBarColor(0xff173d33);getWindow().setNavigationBarColor(0xff173d33);
  try{api=new Api(this);}catch(Exception e){new Vault(this).clear();try{api=new Api(this);}catch(Exception impossible){finish();return;}}
  tts=new TextToSpeech(this,status->{if(status==TextToSpeech.SUCCESS){tts.setLanguage(new Locale("es","ES"));tts.setPitch(1.16f);tts.setSpeechRate(1.02f);tts.setOnUtteranceProgressListener(new UtteranceProgressListener(){public void onStart(String id){}public void onError(String id){onDone(id);}public void onDone(String id){main.postDelayed(()->{if(awaitingWakeCommand){awaitingWakeCommand=false;startRecognition(true);}else if(wake)startRecognition(false);},450);}});}});
  web=new WebView(this);web.setBackgroundColor(0xfff6f8f1);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.getSettings().setAllowFileAccessFromFileURLs(false);web.getSettings().setAllowUniversalAccessFromFileURLs(false);
  web.addJavascriptInterface(new Bridge(),"Native");web.setWebViewClient(new WebViewClient(){@Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest req){Uri u=req.getUrl();if(!"https".equals(u.getScheme())||!"appassets.androidplatform.net".equals(u.getHost())||!u.getPath().startsWith("/assets/"))return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));try{String name=u.getPath().substring(8);if(name.contains(".."))throw new IOException();String mime=name.endsWith(".svg")?"image/svg+xml":name.endsWith(".js")?"text/javascript":"text/html";return new WebResourceResponse(mime,"UTF-8",getAssets().open(name));}catch(Exception e){return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));}}@Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest req){Uri u=req.getUrl();return !("https".equals(u.getScheme())&&"appassets.androidplatform.net".equals(u.getHost())&&u.getPath().startsWith("/assets/"));}@Override public void onPageFinished(WebView v,String url){event("agent",selected);status(api.account().isEmpty()?"Vincula tu cuenta para continuar":"Mantén pulsado para hablar");resumePending();history();if(foreground)ListeningService.recover(MainActivity.this);}});
  setContentView(web);web.loadUrl("https://appassets.androidplatform.net/assets/index.html");
 }
 @Override protected void onResume(){super.onResume();foreground=true;restMorning();main.removeCallbacks(refresh);main.postDelayed(refresh,1200);}
 @Override protected void onPause(){foreground=false;main.removeCallbacks(refresh);stopRecognition();cancelRecording();super.onPause();}
 @Override protected void onDestroy(){stopRecognition();if(recognizer!=null)recognizer.destroy();if(tts!=null){tts.stop();tts.shutdown();}main.removeCallbacksAndMessages(null);worker.shutdownNow();web.removeJavascriptInterface("Native");web.destroy();super.onDestroy();}
 private void event(String key,Object value){try{JSONObject j=Api.object(key,value);main.post(()->web.evaluateJavascript("update("+j+")",null));}catch(Exception ignored){}}
 private void status(String text){event("status",text);}
 private void speak(String text){status(text);if(tts!=null)tts.speak(text,TextToSpeech.QUEUE_FLUSH,null,UUID.randomUUID().toString());}
 private void answer(String text){event("answer",text);speak(text);}
 private void fail(Exception e){busy=false;answer("No he podido completar la petición. "+safeError(e));}
 private String safeError(Exception e){String s=e.getMessage();if(s==null)return "Comprueba la conexión y vuelve a intentarlo.";switch(s){case "unauthorized":case "invalid_or_expired_device":return "Vuelve a vincular tu cuenta.";case "invocation_forbidden":return "Esta cuenta no tiene permiso para controlar la flota.";default:return "No confirmaré ninguna acción sin recibir su resultado.";}}
 private boolean permission(){if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},1);status("Permite el micrófono y vuelve a mantener pulsado.");return false;}return true;}
 final class Bridge {
  @JavascriptInterface public void immersive(boolean on){main.post(()->{if(android.os.Build.VERSION.SDK_INT<30)return;if(on){getWindow().getInsetsController().hide(android.view.WindowInsets.Type.systemBars());getWindow().getInsetsController().setSystemBarsBehavior(android.view.WindowInsetsController.BEHAVIOR_SHOW_TRANSIENT_BARS_BY_SWIPE);}else getWindow().getInsetsController().show(android.view.WindowInsets.Type.systemBars());});}
  @JavascriptInterface public void pair(){main.post(()->startPair());}
  @JavascriptInterface public void openAccount(){main.post(()->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://www.admira.app/conversar"))));}
  @JavascriptInterface public void unlink(){main.post(()->{if(ListeningService.active||busy){speak("Termina primero la escucha o la petición actual.");return;}new AlertDialog.Builder(MainActivity.this).setMessage("¿Desvincular esta cuenta del teléfono?").setPositiveButton("Desvincular",(d,w)->{stopRecognition();wake=false;api.unlink();conversation="";selected="admirito";target="oraculo";event("agent",selected);status("Cuenta desvinculada. Puedes revocar también el dispositivo en admira.app.");}).setNegativeButton("Cancelar",null).show();});}
  @JavascriptInterface public void select(String s){main.post(()->selectAgent(s));}
  @JavascriptInterface public void hold(boolean start){main.post(()->{if(start)startHold();else finishHold();});}
  @JavascriptInterface public void cancelHold(){main.post(()->cancelRecording());}
  @JavascriptInterface public void command(String text){main.post(()->process(text));}
  @JavascriptInterface public void history(){main.post(()->MainActivity.this.history());}
  @JavascriptInterface public void startListening(String kind){main.post(()->beginListening(kind));}
  @JavascriptInterface public void finishListening(){main.post(()->{startService(new Intent(MainActivity.this,ListeningService.class).setAction("finish"));status("Terminando y preparando el resumen…");});}
  @JavascriptInterface public void retryListening(){ListeningService.recover(MainActivity.this);}
  @JavascriptInterface public void photo(){main.post(()->takePhoto());}
  @JavascriptInterface public void identify(){main.post(()->identifyFilm());}
  @JavascriptInterface public void toggleWake(){main.post(()->{if(!permission())return;if(ListeningService.active||busy||recording){speak("Termina primero la escucha o la orden actual.");return;}wake=!wake;event("wake",wake);if(wake){speak("Aquí estoy. Llámame Admirito mientras tengas la app abierta.");}else{stopRecognition();status("Activación por voz apagada");}});}
  @JavascriptInterface public void restToggle(){main.post(()->{boolean enabled=!getPreferences(0).getBoolean("rest",false);getPreferences(0).edit().putBoolean("rest",enabled).apply();speak(enabled?"Estimación de acostarte y primera apertura activada. No mide sueño.":"Estimación desactivada.");});}
  @JavascriptInterface public void restShow(){main.post(()->{android.content.SharedPreferences p=getSharedPreferences("rest-"+api.account(),0);long bed=p.getLong("bed",0),morning=p.getLong("morning",0);answer("Acostarte, estimación por fin de película: "+date(bed)+". Primera apertura de Admirito por la mañana: "+date(morning)+". No equivale a dormir ni a despertarte.");});}
 }
 private String date(long value){return value==0?"sin datos":java.text.DateFormat.getDateTimeInstance(java.text.DateFormat.SHORT,java.text.DateFormat.SHORT).format(new Date(value));}
 private void restMorning(){if(api==null||api.account().isEmpty()||!getPreferences(0).getBoolean("rest",false))return;android.content.SharedPreferences p=getSharedPreferences("rest-"+api.account(),0);long bed=p.getLong("bed",0),now=System.currentTimeMillis();int hour=Calendar.getInstance().get(Calendar.HOUR_OF_DAY);if(hour>=4&&hour<15&&now-bed>7200000&&now-bed<72000000&&p.getLong("morning",0)<bed)p.edit().putLong("morning",now).apply();}
 private void selectAgent(String name){if(!Arrays.asList("admirito","bugito","supervisor").contains(name))return;if(holding||busy)return;selected=name;target=name.equals("admirito")?"oraculo":name;event("agent",name);speak(name.equals("admirito")?"Aquí está tu Admirito.":"Canal de "+name+" seleccionado.");}
 private void startPair(){if(busy||ListeningService.active)return;challenge=null;worker.execute(()->{try{JSONObject c=api.json("agents/devices/start",Api.object("client","android"));challenge=Api.object("device_id",c.getString("device_id"),"secret",c.getString("secret"));pairUntil=System.currentTimeMillis()+c.getLong("expires_in")*1000;event("code",c.getString("code"));status("Aprueba este código en admira.app → Conversar → Continuar en otro dispositivo.");main.postDelayed(this::pollPair,3500);}catch(Exception e){fail(e);}});}
 private void pollPair(){JSONObject c=challenge;if(c==null)return;if(System.currentTimeMillis()>pairUntil){challenge=null;status("El código ha caducado. Pide otro.");return;}worker.execute(()->{try{JSONObject r=api.json("agents/devices/poll",c);if(r.optString("status").equals("paired")){api.paired(r.getString("account_id"));challenge=null;conversation="";event("code","");speak("Cuenta vinculada. Seguimos donde lo dejamos.");ensureConversation();history();}else main.postDelayed(this::pollPair,3500);}catch(Exception e){challenge=null;fail(e);}});}
 private synchronized String ensureConversation() throws Exception {if(api.account().isEmpty())throw new IOException("unauthorized");if(!conversation.isEmpty())return conversation;JSONObject list=api.json("agents/conversations",null);JSONArray rows=list.getJSONArray("conversations");conversation=rows.length()>0?rows.getJSONObject(0).getString("id"):api.json("agents/conversations",new JSONObject()).getJSONObject("conversation").getString("id");return conversation;}
 private void history(){if(api==null||api.account().isEmpty()||busy)return;worker.execute(()->{try{JSONArray rows=api.json("agents/conversations/"+ensureConversation(),null).getJSONArray("messages");StringBuilder text=new StringBuilder();for(int i=Math.max(0,rows.length()-6);i<rows.length();i++){JSONObject row=rows.getJSONObject(i);text.append(row.optString("role").equals("user")?"Tú: ":"Admirito: ").append(row.optString("content")).append("\n\n");}if(text.length()>0)event("answer",text.toString());}catch(Exception e){status("No se ha podido recuperar la conversación.");}});}
 private void startHold(){if(!permission()||busy||ListeningService.active||api.account().isEmpty()){if(api.account().isEmpty())speak("Vincula primero tu cuenta.");return;}stopRecognition();if(tts!=null)tts.stop();holding=true;try{commandFile=new File(getCacheDir(),"command.m4a");recorder=new MediaRecorder();recorder.setAudioSource(MediaRecorder.AudioSource.MIC);recorder.setOutputFormat(MediaRecorder.OutputFormat.MPEG_4);recorder.setAudioEncoder(MediaRecorder.AudioEncoder.AAC);recorder.setAudioSamplingRate(16000);recorder.setAudioChannels(1);recorder.setAudioEncodingBitRate(64000);recorder.setOutputFile(commandFile.getPath());recorder.prepare();recorder.start();recording=true;status("Te escucho… suelta para enviar");main.postDelayed(()->{if(recording)finishHold();},45000);}catch(Exception e){cancelRecording();speak("No he podido abrir el micrófono.");}}
 private void cancelRecording(){holding=false;recording=false;if(recorder!=null){try{recorder.stop();}catch(Exception ignored){}recorder.release();recorder=null;}if(commandFile!=null)commandFile.delete();}
 private void finishHold(){if(!holding||!recording)return;holding=false;recording=false;try{recorder.stop();recorder.release();recorder=null;}catch(Exception e){cancelRecording();speak("No he oído una orden completa.");return;}busy=true;status("Entendiendo tu orden…");worker.execute(()->{try{String text=api.request("agents/transcribe",java.nio.file.Files.readAllBytes(commandFile.toPath()),"audio/mp4",true).optString("text");commandFile.delete();main.post(()->{busy=false;process(text);});}catch(Exception e){commandFile.delete();fail(e);}});}
 private void stopRecognition(){if(recognizer!=null){recognizer.cancel();}awaitingWakeCommand=false;}
 private void startRecognition(boolean command){if(!foreground||!wake||recording||busy||ListeningService.active)return;if(!SpeechRecognizer.isRecognitionAvailable(this)){wake=false;event("wake",false);status("Este Android no ofrece reconocimiento por voz. Mantén pulsado la mascota.");return;}if(recognizer==null)recognizer=SpeechRecognizer.createSpeechRecognizer(this);recognizer.setRecognitionListener(new RecognitionListener(){public void onReadyForSpeech(Bundle b){}public void onBeginningOfSpeech(){}public void onRmsChanged(float f){}public void onBufferReceived(byte[] b){}public void onEndOfSpeech(){}public void onPartialResults(Bundle b){}public void onEvent(int t,Bundle b){}public void onError(int code){if(wake&&foreground&&!busy)main.postDelayed(()->startRecognition(false),2500);}public void onResults(Bundle b){ArrayList<String> list=b.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION);String text=list==null||list.isEmpty()?"":list.get(0);String normalized=Commands.normalize(text);if(command){process(text);return;}if(normalized.contains("admirito")){String after=normalized.substring(normalized.indexOf("admirito")+8).trim();if(!after.isEmpty())process(after);else{awaitingWakeCommand=true;speak("¿Sí? Te escucho.");}}else main.postDelayed(()->startRecognition(false),500);}});Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH).putExtra(RecognizerIntent.EXTRA_LANGUAGE,"es-ES").putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM).putExtra(RecognizerIntent.EXTRA_PARTIAL_RESULTS,false);recognizer.startListening(i);}
 private void process(String raw){if(busy||ListeningService.active)return;String text=raw.trim();if(text.isEmpty()){speak("No he entendido la orden. ¿Puedes repetirla?");return;}if(text.length()>1800){speak("La orden es demasiado larga.");return;}String invoke=Commands.invocation(text);if(invoke!=null){if(invoke.equals("admirito")){selectAgent("admirito");return;}if(invoke.equals("bugito")||invoke.equals("supervisor")){selected=invoke;event("agent",selected);}target=invoke;}
  String tour=Commands.tour(text);if(tour!=null){suite(tour);return;}
  String ctrl=Commands.control(text);String requestText=ctrl!=null?Commands.controlInstruction(ctrl):text; if(ctrl==null&&invoke==null&&selected.equals("admirito")&&!Commands.strip(text).startsWith("demo "))requestText="CONSULTA DE ADMIRITO AL AGENTE. Carlos ha dicho (JSON): "+JSONObject.quote(text)+". Si es una pregunta, respóndela. Si es una orden no reconocida, devuelve tu interpretación y pide la aclaración necesaria. No ejecutes acciones desde esta consulta ni inventes que has hecho nada.";
  busy=true;stopRecognition();speak("Voy a consultar a "+target+".");final String send=requestText;worker.execute(()->{try{String thread=ensureConversation(),id=UUID.randomUUID().toString();JSONObject body=Api.object("target",target,"text",send,"request_id",id);String n=Commands.strip(text);if(n.startsWith("demo ")&&n.contains(" en ")){JSONObject cat=new JSONObject(readAsset("RemoteDemos.json"));String[] parts=n.substring(5).split(" en ");String demo=findAlias(cat.getJSONObject("demos"),parts[0]),dest=findAlias(cat.getJSONObject("destinations"),parts.length>1?parts[1]:"");if(demo!=null&&dest!=null)body=Api.object("target","oraculo","text",send,"demo",Api.object("id",demo,"destination",dest),"request_id",id);}
   // Save before POST. A lost reply is recovered only with GET, never by a new action.
   getSharedPreferences("pending",0).edit().putString(api.account(),Api.object("conversation",thread,"request",id).toString()).commit();
   JSONObject r=api.json("agents/conversations/"+thread+"/invocations",body);pollInvocation(thread,id,r);
  }catch(Exception e){fail(e);}});
 }
 private String findAlias(JSONObject entries,String text)throws Exception{Iterator<String> keys=entries.keys();while(keys.hasNext()){String key=keys.next();JSONArray aliases=entries.getJSONObject(key).getJSONArray("aliases");for(int i=0;i<aliases.length();i++)if(aliases.getString(i).equals(text))return key;}return null;}
 private void pollInvocation(String thread,String id,JSONObject result)throws Exception{for(int i=0;i<200;i++){String state=result.optString("state");if(state.equals("complete")){getSharedPreferences("pending",0).edit().remove(api.account()).commit();busy=false;answer(result.optString("answer","El agente no ha enviado una respuesta."));return;}if(Arrays.asList("failed","uncertain","blocked").contains(state)){busy=false;answer(result.optString("message","No puedo confirmar que la orden se haya ejecutado. No la repetiré automáticamente."));return;}Thread.sleep(3000);result=api.json("agents/conversations/"+thread+"/invocations/"+id,null);}busy=false;status("Sigo esperando al agente. La petición se conserva; no se enviará otra vez.");}
 private void resumePending(){if(api.account().isEmpty()||busy)return;String saved=getSharedPreferences("pending",0).getString(api.account(),"");if(saved.isEmpty())return;busy=true;worker.execute(()->{try{JSONObject p=new JSONObject(saved);String thread=p.getString("conversation"),id=p.getString("request");pollInvocation(thread,id,api.json("agents/conversations/"+thread+"/invocations/"+id,null));}catch(Exception e){fail(e);}});}
 private String readAsset(String path)throws IOException {try(InputStream in=getAssets().open(path)){return new String(Api.read(in),java.nio.charset.StandardCharsets.UTF_8);}}
 private void suite(String command){stopRecognition();speak("Voy a abrir el tour en el modo Experto.");WebView suite=new WebView(this);suite.getSettings().setJavaScriptEnabled(true);suite.getSettings().setDomStorageEnabled(true);suite.getSettings().setAllowFileAccess(false);suite.getSettings().setAllowContentAccess(false);Dialog dialog=new Dialog(this,android.R.style.Theme_Material_Light_NoActionBar_Fullscreen);android.widget.LinearLayout box=new android.widget.LinearLayout(this);box.setOrientation(android.widget.LinearLayout.VERTICAL);Button close=new Button(this);close.setText("Volver a Admirito");close.setOnClickListener(v->dialog.dismiss());box.addView(close);box.addView(suite,new android.widget.LinearLayout.LayoutParams(-1,0,1));dialog.setContentView(box);dialog.setOnDismissListener(d->{suite.destroy();});suite.setWebViewClient(new WebViewClient(){boolean sent;int tries;private boolean trusted(String url){Uri u=Uri.parse(url);return "https".equals(u.getScheme())&&Arrays.asList("www.admira.biz","admira.biz").contains(u.getHost());}@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest req){return !trusted(req.getUrl().toString());}@Override public void onPageFinished(WebView v,String url){if(!trusted(url))return;try{v.evaluateJavascript(readAsset("SuiteExpertBridge.js"),null);Runnable check=new Runnable(){public void run(){if(sent||!dialog.isShowing()||!trusted(v.getUrl()))return;v.evaluateJavascript("Boolean(window.AdmiritoSuiteBridge?.ready())",r->{if(r.equals("true")){sent=true;v.evaluateJavascript("window.AdmiritoSuiteBridge.execute("+JSONObject.quote(command)+","+JSONObject.quote(UUID.randomUUID().toString())+")",null);speak("Orden enviada al modo Experto. Comprueba el recorrido en pantalla.");}else if(++tries<40)main.postDelayed(this,500);else speak("El modo Experto no está disponible. No he enviado la orden.");});}};check.run();}catch(Exception e){speak("No se ha podido abrir el modo Experto.");}}});dialog.show();suite.loadUrl("https://www.admira.biz/");}
 private void beginListening(String kind){if(!Arrays.asList("movie","meeting").contains(kind)||busy||ListeningService.active||!permission())return;stopRecognition();if(tts!=null)tts.stop();worker.execute(()->{try{String thread=ensureConversation();Intent i=new Intent(this,ListeningService.class).setAction("start").putExtra("conversation",thread).putExtra("account",api.account()).putExtra("kind",kind).putExtra("rest",getPreferences(0).getBoolean("rest",false));main.post(()->{if(!foreground){status("Abre la app para iniciar la escucha.");return;}if(android.os.Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},2);startForegroundService(i);status("Escucha iniciada. Puedes bloquear el teléfono; consulta la notificación.");});}catch(Exception e){fail(e);}});}
 private void takePhoto(){if(ListeningService.active){speak("Haz la foto antes de iniciar la escucha.");return;}try{startActivityForResult(new Intent(android.provider.MediaStore.ACTION_IMAGE_CAPTURE),40);}catch(Exception e){speak("No se ha podido abrir la cámara.");}}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==40&&result==RESULT_OK&&data!=null){Bitmap b=(Bitmap)data.getExtras().get("data");if(b==null)return;try{File f=new File(getNoBackupFilesDir(),"projection-"+api.account()+".jpg");try(FileOutputStream out=new FileOutputStream(f)){b.compress(Bitmap.CompressFormat.JPEG,85,out);}event("photo","data:image/jpeg;base64,"+android.util.Base64.encodeToString(java.nio.file.Files.readAllBytes(f.toPath()),android.util.Base64.NO_WRAP));status("Foto preparada para la próxima escucha de película.");}catch(Exception e){fail(e);}}}
 private void identifyFilm(){worker.execute(()->{try{JSONObject note=ListeningService.latest(this,api.account());if(!note.optString("kind").equals("movie")||!note.optBoolean("complete"))throw new IOException("summary_required");File f=new File(new File(getNoBackupFilesDir(),"listening"),note.getString("id")+"/photo.jpg");JSONObject r=api.request("agents/listening/"+note.getString("id")+"/identify",java.nio.file.Files.readAllBytes(f.toPath()),"image/jpeg");answer(r.optString("message")+(r.isNull("title")?"":" "+r.optString("title")));}catch(Exception e){answer("Necesito una escucha de película terminada, su resumen y una foto. No voy a inventar un título.");}});}
}
